using System;using System.Drawing;using System.Linq;using System.Reflection;using System.Diagnostics;using System.Threading;using System.Windows.Forms;
namespace Frociart.Tests {
 // In-process geometry/paint harness: actual Windows focus/capture policy is covered
 // separately by CanvasTests and the real MainForm gesture suites.
 sealed class ConnectionCanvas:FlowCanvas {protected override Keys GetInteractionModifiers(){return Keys.None;}protected override void OnMouseCaptureChanged(EventArgs e){}protected override void OnLostFocus(EventArgs e){} }
 sealed class ConnectionHost:Form {internal readonly ConnectionCanvas Canvas=new ConnectionCanvas{Dock=DockStyle.Fill};internal Diagram Document{get{return Canvas.Diagram;}}internal ConnectionHost(object unused,bool isolated){Controls.Add(Canvas);}internal void EnterEditor(){}internal void SetDocument(Diagram d,object path,bool dirty){Canvas.Diagram=d;Canvas.SelectNode(null);} }
 static class ConnectionRegressionTests {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static int checks;
 static object Call(object o,string n,params object[] a){for(Type t=o.GetType();t!=null;t=t.BaseType){var m=t.GetMethods(F|BindingFlags.Static).FirstOrDefault(v=>v.Name==n&&v.GetParameters().Length==a.Length);if(m!=null)return m.Invoke(o,a);}throw new MissingMethodException(n);}
 static T Get<T>(object o,string n){for(Type t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F);if(f!=null)return (T)f.GetValue(o);}throw new MissingFieldException(n);}
 static void Check(bool b,string n){if(!b)throw new Exception(n);checks++;Console.WriteLine("PASS "+n);}
 static void Pump(int ms=0){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(3);}while(DateTime.UtcNow<end);}
 static void Mouse(FlowCanvas c,string n,Point p,MouseButtons button=MouseButtons.Left){Call(c,n,new MouseEventArgs(button,1,p.X,p.Y,0));if(c is ConnectionCanvas)c.Capture=false;}
 static Point Center(FlowCanvas c,FlowNode n){var b=FlowCanvas.GetNodeBounds(n);return Point.Round(c.WorldToClient(new PointF(b.X+b.Width/2,b.Y+b.Height/2)));}
 static Diagram Fixture(bool decision){var d=new Diagram();d.Nodes.AddRange(new[]{new FlowNode{Id="s",Kind=NodeKind.Start,X=320,Y=0},new FlowNode{Id="m",Kind=decision?NodeKind.Decision:NodeKind.Process,X=decision?260:296,Y=220,Text="x > 0"},new FlowNode{Id="e",Kind=NodeKind.End,X=320,Y=680},new FlowNode{Id="side",Kind=NodeKind.Process,X=900,Y=200,Text="x = 1"}});d.Edges.AddRange(new[]{new FlowEdge{Id="in",From="s",To="m"},new FlowEdge{Id="out",From="m",To="e",Branch=decision?"true":"next"}});return d;}
 static void Hover(FlowCanvas c,FlowEdge edge){var d=c.Diagram;var route=c.GetExportRoute(d.Nodes.First(n=>n.Id==edge.From),d.Nodes.First(n=>n.Id==edge.To),edge.Branch);int j=Enumerable.Range(1,route.Count-1).OrderByDescending(i=>Math.Abs(route[i].X-route[i-1].X)+Math.Abs(route[i].Y-route[i-1].Y)).First();var mid=new PointF((route[j].X+route[j-1].X)/2,(route[j].Y+route[j-1].Y)/2);var t=new double[250];for(int i=0;i<t.Length;i++){var p=Point.Round(c.WorldToClient(new PointF(mid.X+(i%9-4)*.2f,mid.Y+(i%7-3)*.2f)));var w=Stopwatch.StartNew();Mouse(c,"OnMouseMove",p,MouseButtons.None);t[i]=w.Elapsed.TotalMilliseconds;}Array.Sort(t);Console.WriteLine("HOVER branch="+edge.Branch+" zoom="+c.Zoom+" median_ms="+t[t.Length/2]+" p95_ms="+t[237]);}
 static void MovingRoute(ConnectionHost form){
  var c=form.Canvas;var d=Fixture(true);var loose=d.Nodes.First(n=>n.Id=="side");loose.X=-850;loose.Y=100;d.Nodes.First(n=>n.Id=="e").Kind=NodeKind.Process;d.Nodes.First(n=>n.Id=="e").Y=-160;d.Edges.RemoveAll(e=>e.From=="m");d.Edges.First().To="e";
  d.Edges.Add(new FlowEdge{Id="return",From="m",To="e",Branch="true"});form.SetDocument(d,null,false);c.SnapToGrid=false;c.FitToView();Pump(450);
  var start=Center(c,loose);Mouse(c,"OnMouseDown",start);Mouse(c,"OnMouseMove",Point.Round(c.WorldToClient(new PointF(-250,160))));
  var route=c.GetExportRoute(d.Nodes.First(n=>n.Id=="m"),d.Nodes.First(n=>n.Id=="e"),"true");int i=Enumerable.Range(1,route.Count-1).OrderByDescending(j=>Math.Abs(route[j].Y-route[j-1].Y)).First();
  var middle=new PointF((route[i].X+route[i-1].X)/2,(route[i].Y+route[i-1].Y)/2);var drop=Point.Round(c.WorldToClient(middle));Mouse(c,"OnMouseMove",drop);
  // Moving an unrelated obstacle reroutes the return arrow. Candidate and visible route must agree.
  route=c.GetExportRoute(d.Nodes.First(n=>n.Id=="m"),d.Nodes.First(n=>n.Id=="e"),"true");i=Enumerable.Range(1,route.Count-1).OrderByDescending(j=>Math.Abs(route[j].Y-route[j-1].Y)).First();middle=new PointF((route[i].X+route[i-1].X)/2,(route[i].Y+route[i-1].Y)/2);
  var target=Get<object>(c,"insertHover");var routes=(System.Collections.IEnumerable)Get<object>(c,"insertRoutes");bool matched=false;
  foreach(object r in routes){if(Get<string>(r,"Id")!="return")continue;var points=Get<PointF[]>(r,"Points");float best=999999;for(int j=1;j<points.Length;j++)best=Math.Min(best,(float)Call(c,"InsertSegmentDistance",middle,points[j-1],points[j]));matched=best<1;}
  Check(matched,"Insertion candidates follow a return arrow after its obstacle moves");Call(c,"OnKeyDown",new KeyEventArgs(Keys.Escape));Pump();
 }
 static void PaintCost(ConnectionHost form){var c=form.Canvas;form.SetDocument(Examples.Parity(),null,false);c.Zoom=2.5f;c.CenterOnNode("check");Pump(450);var edge=form.Document.Edges.First(e=>e.From=="check"&&e.Branch=="true");var route=c.GetExportRoute(form.Document.Nodes.First(n=>n.Id==edge.From),form.Document.Nodes.First(n=>n.Id==edge.To),edge.Branch);var p=Point.Round(c.WorldToClient(new PointF((route[0].X+route[1].X)/2,route[0].Y)));c.BeginPalettePreview(NodeKind.Process,p);using(var bitmap=new Bitmap(c.Width,c.Height))using(var g=Graphics.FromImage(bitmap)){var samples=new double[30];for(int i=0;i<samples.Length;i++){c.MovePalettePreview(new Point(p.X+i%3,p.Y+i%2));var watch=Stopwatch.StartNew();Call(c,"OnPaint",new PaintEventArgs(g,c.ClientRectangle));samples[i]=watch.Elapsed.TotalMilliseconds;}Array.Sort(samples);Console.WriteLine("GLOW_PAINT zoom=2.5 median_ms="+samples[15]+" p95_ms="+samples[28]);foreach(string part in new[]{"PaintInsertPreview","PaintPalettePreview","PaintExperience","UpdateFrame","DrawGrid","DrawScene","PaintSceneRegion"}){var t=new double[10];for(int j=0;j<t.Length;j++){var watch=Stopwatch.StartNew();if(part=="PaintSceneRegion"||part=="DrawGrid")Call(c,part,g,c.ClientRectangle);else if(part=="DrawScene"){var state=g.Save();var origin=c.WorldToClient(PointF.Empty);g.Transform=new System.Drawing.Drawing2D.Matrix(c.Zoom,0,0,c.Zoom,origin.X,origin.Y);Call(c,part,g,new RectangleF(-100000,-100000,200000,200000),true,c.Zoom);g.Restore(state);}else Call(c,part,g);t[j]=watch.Elapsed.TotalMilliseconds;}Array.Sort(t);Console.WriteLine("PART "+part+" median_ms="+t[5]);}}using(var bitmap=new Bitmap(c.Width,c.Height))using(var g=Graphics.FromImage(bitmap)){var origin=c.WorldToClient(PointF.Empty);g.Transform=new System.Drawing.Drawing2D.Matrix(c.Zoom,0,0,c.Zoom,origin.X,origin.Y);foreach(object v in (Array)Get<object>(c,"_edgeVisuals")){var watch=Stopwatch.StartNew();for(int i=0;i<10;i++)Call(c,"DrawEdge",g,Get<FlowEdge>(v,"Model"),Get<object>(v,"Points"),v.GetType().GetProperty("Path",F).GetValue(v,null),new RectangleF(-100000,-100000,200000,200000),true,c.Zoom);Console.WriteLine("EDGE "+Get<string>(v,"Id")+" ms="+watch.Elapsed.TotalMilliseconds/10);}foreach(object v in (Array)Get<object>(c,"_nodeVisuals")){var watch=Stopwatch.StartNew();for(int i=0;i<10;i++)Call(c,"DrawNode",g,v,true,c.Zoom);Console.WriteLine("NODE "+Get<string>(v,"Id")+" ms="+watch.Elapsed.TotalMilliseconds/10);}}c.EndPalettePreview();}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);using(var form=new ConnectionHost(null,true)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-4000,-3000);form.Size=new Size(1400,1000);form.Show();form.EnterEditor();Pump();var c=form.Canvas;if(Environment.GetEnvironmentVariable("FROCIART_PERF_ONLY")=="1"){PaintCost(form);return 0;}
  form.SetDocument(Examples.Parity(),null,false);c.Zoom=2.5f;foreach(var e in form.Document.Edges.Where(e=>e.From=="check"))Hover(c,e);
  foreach(bool decision in new[]{false,true})foreach(int wait in new[]{0,100,450}){form.SetDocument(Fixture(decision),null,false);c.SnapToGrid=false;c.FitToView();Pump(450);var n=form.Document.Nodes.First(x=>x.Id=="m");var p=Center(c,n);Mouse(c,"OnMouseDown",p);Pump(1750);Console.WriteLine("STATE wait="+wait+" hold="+Get<long>(c,"holdStart")+" fill="+Get<float>(c,"holdFill")+" detached="+Get<bool>(c,"stickerDetached")+" node="+(Get<FlowNode>(c,"_dragNode")==null?"null":Get<FlowNode>(c,"_dragNode").Id));Mouse(c,"OnMouseUp",p);Check(!form.Document.Edges.Any(e=>e.From=="m"||e.To=="m"),"Stationary peel fully detaches "+decision);Pump(wait);
   var line=form.Document.Edges.Single();var route=c.GetExportRoute(form.Document.Nodes.First(x=>x.Id==line.From),form.Document.Nodes.First(x=>x.Id==line.To),line.Branch);var drop=Point.Round(c.WorldToClient(new PointF(route[0].X,410)));
   // Start inside the same detached block, then leave and return over the original bypass.
   p=Center(c,n);Mouse(c,"OnMouseDown",p);Mouse(c,"OnMouseMove",new Point(p.X+120,p.Y+5));Mouse(c,"OnMouseMove",drop);Check(Get<bool>(c,"insertReady"),"Original bypass accepts next gesture, decision="+decision+" wait="+wait);
   if(decision){using(var timer=new System.Windows.Forms.Timer{Interval=15}){timer.Tick+=delegate{var dialog=Application.OpenForms.OfType<BranchContinuationDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();foreach(Control v in dialog.Controls)if(v is Button&&v.Text=="Sì")((Button)v).PerformClick();};timer.Start();Mouse(c,"OnMouseUp",drop);}}else Mouse(c,"OnMouseUp",drop);
   Check(form.Document.Edges.Any(e=>e.To=="m")&&form.Document.Edges.Any(e=>e.From=="m"),"Original bypass reinsertion commits without another location "+decision);Pump(450);
  }
  PaintCost(form);MovingRoute(form);form.SetDocument(new Diagram(),null,false);form.Close();}Console.WriteLine("CONNECTION_REGRESSION_FINISHED checks="+checks+" errors=0");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}
